package builder

// Verifies the Go keystream is byte-identical to the C loader's CryptDecodeBuffer
// (payloads/Shellcode/Source/Utils.c), so an encode in Go decodes correctly in C.

import (
	"bytes"
	"testing"
)

// keystream generated by the C CryptDecodeBuffer for key "HAVOC_CRYPT_KEY_MARKER" padded to
// 31 chars, over 64 zero bytes (compiled with MSVC from Source/Utils.c logic).
var cReferenceKeystream = []byte{
	0xc8, 0x21, 0x29, 0xe1, 0x25, 0xfa, 0x35, 0x2b,
	0xd7, 0x96, 0x90, 0xd2, 0xc4, 0x98, 0xa2, 0x82,
	0xac, 0x5e, 0x9f, 0x87, 0xd7, 0x8b, 0x89, 0x9b,
	0x9a, 0x60, 0x4d, 0x82, 0x94, 0x50, 0x00, 0x05,
	0x9c, 0xb1, 0x0b, 0x58, 0xc6, 0x39, 0x77, 0x12,
	0xc1, 0x72, 0x32, 0x16, 0xcb, 0x39, 0x84, 0xad,
	0x65, 0x66, 0xdf, 0xbb, 0x71, 0x97, 0x0a, 0x1f,
	0x4b, 0x45, 0x72, 0x23, 0xf0, 0x8b, 0x9a, 0x99,
}

// referenceKey matches the C generator: "HAVOC_CRYPT_KEY_MARKER" padded with '_' to 31 chars.
var referenceKey = func() []byte {
	k := make([]byte, 31)
	copy(k, "HAVOC_CRYPT_KEY_MARKER")
	for i := 22; i < 31; i++ {
		k[i] = '_'
	}
	return k
}()

func keystream(Key []byte, n int) []byte {
	buf := make([]byte, n)
	CryptEncodeBuffer(buf, Key) // xor against zeros == raw keystream
	return buf
}

func TestKeystreamMatchesC(t *testing.T) {
	got := keystream(referenceKey, len(cReferenceKeystream))
	if !bytes.Equal(got, cReferenceKeystream) {
		t.Fatalf("keystream mismatch vs C\n got: %x\nwant: %x", got, cReferenceKeystream)
	}
}

func TestCryptRoundTrip(t *testing.T) {
	key := referenceKey
	data := make([]byte, 4096)
	for i := range data {
		data[i] = byte(i)
	}
	enc := make([]byte, len(data))
	copy(enc, data)
	CryptEncodeBuffer(enc, key)

	dec := make([]byte, len(enc))
	copy(dec, enc)
	CryptEncodeBuffer(dec, key) // symmetric: same op decrypts

	if !bytes.Equal(dec, data) {
		t.Fatal("round trip failed: decrypt(encrypt(x)) != x")
	}
	if bytes.Equal(enc, data) {
		t.Fatal("encoding did not change the buffer")
	}
}
